1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
31	    @Mapping(target = "identityKey",
32	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
33	    @Mapping(target = "bulkSignupWarning",
34	            expression = "java(owner.getBulkSignupWarning() != null && owner.getBulkSignupWarning())")
35	    @Mapping(target = "possibleDuplicate",
36	            expression = "java(owner.getPossibleDuplicateOf() != null)")
37	    @Mapping(target = "deleted",
38	            expression = "java(owner.getDeleted() != null && owner.getDeleted())")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /** The stored E.164 'telephone' formatted for humans: the country code, a space, then the
45	     *  national digits grouped in threes (e.g. '+61 412 345 678'). The raw 'telephone' stays
46	     *  E.164. Null when the stored value is not a recognised E.164 number. */
47	    default String telephoneDisplay(Owner owner) {
48	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
49	                .toDisplayOrNull(owner.getTelephone());
50	    }
51	
52	    /** Age band derived from birthDate relative to registrationDate: 'MINOR' when under
53	     *  18, 'ADULT' from 18 to 64, 'SENIOR' at 65 or over. Null when either date is absent. */
54	    default String ageBand(Owner owner) {
55	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
56	            return null;
57	        }
58	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
59	        if (age < 18) {
60	            return "MINOR";
61	        }
62	        if (age < 65) {
63	            return "ADULT";
64	        }
65	        return "SENIOR";
66	    }
67	
68	    /** 'EMAIL' when the owner has a non-blank email address, otherwise 'PHONE'. */
69	    default String contactPreference(Owner owner) {
70	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
71	    }
72	
73	    /** The owner's salutation: 'title' + ' ' + lastName when a title is present, else just the
74	     *  lastName. */
75	    default String salutation(Owner owner) {
76	        String title = owner.getTitle();
77	        if (title != null && !title.isBlank()) {
78	            return title + " " + owner.getLastName();
79	        }
80	        return owner.getLastName();
81	    }
82	
83	    /** Upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
84	    default String initials(Owner owner) {
85	        return owner.getFirstName().substring(0, 1).toUpperCase()
86	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
87	    }
88	
89	    /** Membership number '<customerCode>-M<YY>', YY = last two digits of the
90	     *  registrationDate year. Null unless both source fields are present. */
91	    default String membershipNumber(Owner owner) {
92	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
93	            return null;
94	        }
95	        return String.format("%s-M%02d", owner.getCustomerCode(),
96	                owner.getRegistrationDate().getYear() % 100);
97	    }
98	
99	    /** A single Luhn check digit (0-9) computed over the digits contained in the
100	     *  owner's customerCode. Null when the customerCode is absent. */
101	    default Integer checkDigit(Owner owner) {
102	        String code = owner.getCustomerCode();
103	        if (code == null) {
104	            return null;
105	        }
106	        int sum = 0;
107	        boolean dbl = true;
108	        for (int i = code.length() - 1; i >= 0; i--) {
109	            char c = code.charAt(i);
110	            if (c < '0' || c > '9') {
111	                continue;
112	            }
113	            int d = c - '0';
114	            if (dbl) {
115	                d *= 2;
116	                if (d > 9) {
117	                    d -= 9;
118	                }
119	            }
120	            sum += d;
121	            dbl = !dbl;
122	        }
123	        return (10 - (sum % 10)) % 10;
124	    }
125	
126	    /** Membership points: starts at 0, adds 2 when an email is present, adds 1 when
127	     *  namesakeCount is 0, adds 2 for a household of 3 or more, and adds 3 for tenure
128	     *  (more than 365 days between the registrationDate and today). */
129	    default Integer membershipPoints(Owner owner) {
130	        int points = 0;
131	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
132	        if (hasEmail) {
133	            points += 2;
134	        }
135	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
136	            points += 1;
137	        }
138	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
139	            points += 2;
140	        }
141	        if (owner.getRegistrationDate() != null
142	                && java.time.temporal.ChronoUnit.DAYS.between(
143	                        owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
144	            points += 3;
145	        }
146	        return points;
147	    }
148	
149	    /** Numeric membership level from 1 to 4, mapped from membershipPoints: level 1 for
150	     *  0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. */
151	    default Integer membershipLevel(Owner owner) {
152	        int points = membershipPoints(owner);
153	        if (points <= 1) {
154	            return 1;
155	        }
156	        if (points <= 3) {
157	            return 2;
158	        }
159	        if (points <= 5) {
160	            return 3;
161	        }
162	        return 4;
163	    }
164	
165	    /** The owner's locality: the REGION component of the customerCode ('<REGION>-<HASH8>'),
166	     *  which is derived from the postcode at creation. 'UNKNOWN' when the customerCode is absent
167	     *  or carries no region prefix. Derived from the region-and-hash identity so it always agrees
168	     *  with the code, membership number and check digit. */
169	    default String locality(Owner owner) {
170	        String code = owner.getCustomerCode();
171	        if (code == null) {
172	            return "UNKNOWN";
173	        }
174	        int dash = code.indexOf('-');
175	        return dash <= 0 ? "UNKNOWN" : code.substring(0, dash);
176	    }
177	
178	    /** The IANA timezone name derived from the owner's locality/region using the fixed
179	     *  region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
180	     *  QLD->Australia/Brisbane). Null when the locality is not a region in the table. */
181	    default String timezone(Owner owner) {
182	        return org.springframework.samples.petclinic.rest.function.owner.PostcodeRegions
183	                .timezoneForRegion(locality(owner));
184	    }
185	
186	    Owner toOwner(OwnerDto ownerDto);
187	
188	    @Mapping(target = "id", ignore = true)
189	    @Mapping(target = "pets", ignore = true)
190	    Owner toOwner(OwnerFieldsDto ownerDto);
191	
192	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
193	
194	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
195	
196	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
197	        OwnerPageDto ownerPageDto = new OwnerPageDto();
198	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
199	        ownerPageDto.setPage(ownerPage.getNumber());
200	        ownerPageDto.setSize(ownerPage.getSize());
201	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
